<x-theme::section data-theme-block="posts"><x-theme::container>@if(!empty($settings['title']))<x-theme::heading :level="2" class="theme-section-title">{{ $settings['title'] }}</x-theme::heading>@endif<div class="theme-blog-grid">@forelse($posts as $post)<article class="theme-blog-card">@if($post->thumbnail_url)<img src="{{ $post->thumbnail_url }}" alt="{{ $post->title }}" loading="lazy">@else<div class="theme-blog-card__placeholder" aria-hidden="true">◇</div>@endif<div><h3><a href="{{ route('articles.show', $post) }}">{{ $post->title }}</a></h3>@if($post->short_information ?? $post->summary ?? null)<p>{{ $post->short_information ?? $post->summary }}</p>@endif</div></article>@empty<x-theme::empty-state title="نوشته‌ای برای نمایش وجود ندارد" />@endforelse</div></x-theme::container></x-theme::section>
